import type { Terminal } from "@xterm/xterm";

import {
  recordCanvasFallback,
  recordWebglContextLoss,
  recordWebglCreated,
  recordWebglDisposed,
  recordWebglLoadFailure,
} from "./terminalRendererMetrics";

export async function loadTerminalAssets() {
  const [xtermModule, fitModule, unicode11Module, searchModule] = await Promise.all([
    import("@xterm/xterm"),
    import("@xterm/addon-fit"),
    import("@xterm/addon-unicode11"),
    import("@xterm/addon-search"),
    import("@xterm/xterm/css/xterm.css"),
  ]);

  return {
    Terminal: xtermModule.Terminal,
    FitAddon: fitModule.FitAddon,
    Unicode11Addon: unicode11Module.Unicode11Addon,
    SearchAddon: searchModule.SearchAddon,
  };
}

export async function attachWebglRenderer(terminal: Terminal, signal?: AbortSignal): Promise<() => void> {
  let addon: InstanceType<(typeof import("@xterm/addon-webgl"))["WebglAddon"]> | null = null;
  let tracked = false;
  let disposed = false;

  const dispose = (canvasFallback: boolean) => {
    if (disposed) return;
    disposed = true;

    try {
      addon?.dispose();
    } finally {
      if (tracked) {
        tracked = false;
        recordWebglDisposed();
      }
      if (canvasFallback) recordCanvasFallback();
    }
  };

  try {
    const { WebglAddon } = await import("@xterm/addon-webgl");
    if (signal?.aborted) return () => undefined;

    addon = new WebglAddon();
    recordWebglCreated();
    tracked = true;

    addon.onContextLoss(() => {
      if (disposed) return;
      recordWebglContextLoss();
      dispose(true);
    });

    terminal.loadAddon(addon);
    return () => dispose(false);
  } catch {
    dispose(false);
    recordWebglLoadFailure();
    recordCanvasFallback();
    return () => undefined;
  }
}

export type WebglLifecycleCounters = {
  created: number;
  active: number;
  disposed: number;
  contextLosses: number;
  loadFailures: number;
  canvasFallbacks: number;
};

declare global {
  var __ORCA_WEBGL_LIFECYCLE__: Readonly<WebglLifecycleCounters> | undefined;
}

const counters: WebglLifecycleCounters = {
  created: 0,
  active: 0,
  disposed: 0,
  contextLosses: 0,
  loadFailures: 0,
  canvasFallbacks: 0,
};

export function getWebglLifecycleCounters(): Readonly<WebglLifecycleCounters> {
  return { ...counters };
}

export function recordWebglCreated() {
  counters.created += 1;
  counters.active += 1;
  publish();
}

export function recordWebglDisposed() {
  counters.disposed += 1;
  counters.active = Math.max(0, counters.active - 1);
  publish();
}

export function recordWebglContextLoss() {
  counters.contextLosses += 1;
  publish();
}

export function recordWebglLoadFailure() {
  counters.loadFailures += 1;
  publish();
}

export function recordCanvasFallback() {
  counters.canvasFallbacks += 1;
  publish();
}

export function resetWebglLifecycleCountersForTests() {
  counters.created = 0;
  counters.active = 0;
  counters.disposed = 0;
  counters.contextLosses = 0;
  counters.loadFailures = 0;
  counters.canvasFallbacks = 0;
  publish();
}

function publish() {
  globalThis.__ORCA_WEBGL_LIFECYCLE__ = Object.freeze(getWebglLifecycleCounters());
}

publish();

import { useEffect, useRef, useState } from "react";

import { terminalHostManager } from "../lib/terminalHostManager";
import { useTerminalSettings } from "../lib/terminalSettings";
import type { TerminalSession } from "../lib/types";
import { TerminalSearchOverlay } from "./TerminalSearchOverlay";

type TerminalPaneProps = {
  session: TerminalSession;
  active: boolean;
  onBell?: () => void;
  onTitleChange?: (title: string) => void;
  searchOpen?: boolean;
  onCloseSearch?: () => void;
};

export function TerminalPane({ session, active, onBell, onTitleChange, searchOpen, onCloseSearch }: TerminalPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [error, setError] = useState<string | null>(null);
  const { settings } = useTerminalSettings();

  useEffect(() => {
    terminalHostManager.applyInstanceSettings(session.id, settings);
  }, [session.id, settings]);

  useEffect(() => {
    terminalHostManager.updateSession(session.id, session);
  }, [session]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    let cancelled = false;

    void terminalHostManager
      .getOrCreate(session, active, onBell, onTitleChange)
      .then((instance) => {
        if (cancelled) return;
        if (!container.contains(instance.element)) {
          container.replaceChildren(instance.element);
        }
        if (active) {
          instance.terminal.focus();
        }

        const fontsReady = typeof document !== "undefined" ? document.fonts?.ready : undefined;
        void fontsReady?.then(() => {
          if (!cancelled && instance.element.clientWidth > 0 && instance.element.clientHeight > 0) {
            instance.fitAddon.fit();
          }
        });
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : "Failed to mount terminal");
      });

    return () => {
      cancelled = true;
    };
  }, [session.id]);

  useEffect(() => {
    const instance = terminalHostManager.getInstance(session.id);
    if (instance) {
      instance.active = active;
      if (active) {
        instance.terminal.focus();
      }
    }
  }, [active, session.id]);

  return (
    <div
      data-testid="terminal-pane-surface"
      className="relative h-full w-full min-h-0 min-w-0 overflow-hidden"
      style={{ backgroundColor: settings.theme.background }}
    >
      <div
        ref={containerRef}
        data-testid="terminal-mount"
        className="relative h-full w-full min-h-0 min-w-0 overflow-hidden"
        style={{ backgroundColor: settings.theme.background }}
      />
      {searchOpen ? (
        <TerminalSearchOverlay
          instance={terminalHostManager.getInstance(session.id)}
          onClose={onCloseSearch ?? (() => undefined)}
        />
      ) : null}
      {error ? (
        <div className="pointer-events-none absolute bottom-3 right-3 max-w-error rounded-md border border-destructive/30 bg-destructive/10 px-2 py-1 text-[11px] text-destructive">
          {error}
        </div>
      ) : null}
    </div>
  );
}

